    private fun minMaxNormalize(scores: List<Double>): List<Double> {
        if (scores.isEmpty()) return scores
        val min = scores.min()
        val max = scores.max()
        val range = max - min
        return if (range <= 0.0) List(scores.size) { 0.5 } else scores.map { (it - min) / range }
    }
}
